"use client";
import * as React from "react";
import { Switch as BaseSwitch } from "@base-ui-components/react/switch";
import { cn } from "@/lib/utils";

// shadcn-style Switch built on the Base UI primitive (§8 default). No @radix import.
export function Switch({ className, ...props }: React.ComponentProps<typeof BaseSwitch.Root>) {
  return (
    <BaseSwitch.Root
      className={cn(
        "relative inline-flex h-5 w-9 shrink-0 items-center rounded-full bg-muted transition-colors data-[checked]:bg-brand",
        className
      )}
      {...props}
    >
      <BaseSwitch.Thumb className="ml-0.5 h-4 w-4 rounded-full bg-background shadow transition-transform data-[checked]:translate-x-4" />
    </BaseSwitch.Root>
  );
}
